keyframes.cssText:
@keyframes fadeIn { 
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes floatUp { 
  0% { opacity: 1; transform: translateY(0px); }
  100% { opacity: 0; transform: translateY(-18px); }
}

@keyframes stat-badge-enter { 
  0% { filter: blur(4px); opacity: 0; translate: 0px 40px; }
  100% { filter: blur(); opacity: 1; translate: 0px; }
}

@keyframes stat-badge-exit { 
  0% { filter: blur(); opacity: 1; translate: 0px; }
  100% { filter: blur(4px); opacity: 0; translate: 0px -40px; }
}

@keyframes logos-carousel-module__A345zq__enter { 
  0% { filter: blur(4px); opacity: 0; translate: 0px 40px; }
  100% { filter: blur(); opacity: 1; translate: 0px; }
}

@keyframes logos-carousel-module__A345zq__exit { 
  0% { filter: blur(); opacity: 1; translate: 0px; }
  100% { filter: blur(4px); opacity: 0; translate: 0px -40px; }
}

@keyframes animated-heading-module___hYpyG__enter { 
  0% { filter: blur(4px); opacity: 0; translate: 0px 40px; }
  100% { filter: blur(); opacity: 1; translate: 0px; }
}

@keyframes animated-heading-module___hYpyG__exit { 
  0% { filter: blur(); opacity: 1; translate: 0px; }
  100% { filter: blur(4px); opacity: 0; translate: 0px -40px; }
}

@keyframes swipe-out-left { 
  0% { transform: var(--y) translateX(var(--swipe-amount-x)); opacity: 1; }
  100% { transform: var(--y) translateX(calc(var(--swipe-amount-x) - 100%)); opacity: 0; }
}

@keyframes swipe-out-right { 
  0% { transform: var(--y) translateX(var(--swipe-amount-x)); opacity: 1; }
  100% { transform: var(--y) translateX(calc(var(--swipe-amount-x) + 100%)); opacity: 0; }
}

@keyframes swipe-out-up { 
  0% { transform: var(--y) translateY(var(--swipe-amount-y)); opacity: 1; }
  100% { transform: var(--y) translateY(calc(var(--swipe-amount-y) - 100%)); opacity: 0; }
}

@keyframes swipe-out-down { 
  0% { transform: var(--y) translateY(var(--swipe-amount-y)); opacity: 1; }
  100% { transform: var(--y) translateY(calc(var(--swipe-amount-y) + 100%)); opacity: 0; }
}

@keyframes sonner-fade-in { 
  0% { opacity: 0; transform: scale(0.8); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes sonner-fade-out { 
  0% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(0.8); }
}

@keyframes hourlySpotsRoll { 
  0% { transform: translateY(0.55em); opacity: 0; }
  100% { transform: none; opacity: 1; }
}

@keyframes hourlySpotsPulse { 
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(0.75); }
}
